'use strict';
const S={user:null,csrf:'',cases:[],users:[],cid:null,data:null,calc:null,scenarioCalc:null,version:0,status:'draft',tab:'overview',year:null,scenario:'base',dirty:false,invalid:new Set(),modal:null,search:'',page:'dashboard',lastSave:null,editRevision:0,saving:null};
const roles={admin:'Adminisztrátor',reviewer:'Jóváhagyó szakértő',analyst:'Elemző',client:'Ügyfél'};
const labels={micro:'Mikrovállalkozás',small:'Kisvállalkozás',medium:'Középvállalkozás',large:'KKV-körön kívüli méret',public:'KKV-körön kívüli – közjogi részesedés'};
const relationLabels={own:'Saját vállalkozás',linked:'Kapcsolódó',partner:'Partner',independent:'Önálló / kizárt',unresolved:'Tisztázandó',consolidated:'Konszolidált adat',scenario:'100%-os feltételezés'};
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',check:'M5 12l4 4L19 6',alert:'M12 9v4 M12 17h.01 M10 3L2 18a2 2 0 0 0 2 3h16a2 2 0 0 0 2-3L14 3a2 2 0 0 0-4 0z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v4a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-4',download:'M12 3v13 M7 11l5 5 5-5 M3 16v4a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-4',logout:'M9 3H4v18h5 M9 12h12 M16 7l5 5-5 5',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M20 21v-2a4 4 0 0 0-3-3.87 M16 3a4 4 0 0 1 0 8 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',building:'M3 21h18 M5 21V3h14v18 M9 7h1 M14 7h1 M9 11h1 M14 11h1 M10 21v-6h4v6',network:'M9 5h6v5H9z M2 17h6v5H2z M16 17h6v5h-6z M12 10v3 M5 17v-4h14v4',calculator:'M6 2h12a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2 M8 6h8 M8 11h1 M15 11h1 M8 15h1 M15 15h1 M8 19h1 M15 19h1',edit:'M16 3l5 5 M3 21l4-1 13-13a3 3 0 0 0-4-4L3 16z',close:'M6 6l12 12 M6 18L18 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',more:'M5 12h.01 M12 12h.01 M19 12h.01',leaf:'M20 4C11 2 2 6 4 15c9 3 16-2 16-11z M4 20l10-10',save:'M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2 M7 3v6h10V3 M7 21v-8h10v8',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'};
const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.file}"/></svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();
const staff=()=>S.user&&S.user.role!=='client';
const canApprove=()=>['admin','reviewer'].includes(S.user?.role);
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Budapest'}).format(new Date());
const yearNow=()=>Number(today().slice(0,4));
const company=(cid)=>S.data?.companies.find(c=>c.id===cid);
const person=(pid)=>S.data?.persons.find(p=>p.id===pid);
const actorName=(cid)=>company(cid)?.name||person(cid)?.name||cid;
const shortDate=(v)=>v?new Intl.DateTimeFormat('hu-HU',{year:'numeric',month:'short',day:'numeric',timeZone:'Europe/Budapest'}).format(new Date(v.length===10?v+'T12:00:00':v)):'–';
function decimal(v){let t=String(v??'').trim().replace(/[\s\u00a0]/g,'');if(!t)return null;if(t.includes(','))t=t.replace(/\./g,'').replace(',','.');if(!/^\d+(\.\d+)?$/.test(t))throw Error('Pozitív számot vagy nullát adjon meg, tizedesvesszővel.');return t;}
function scale(v,power){if(v===null||v===undefined||v==='')return null;let t=String(v),[a,b='']=t.split('.');let digits=a+b,at=a.length+power;if(at<=0)return '0.'+'0'.repeat(-at)+digits;if(at>=digits.length)return digits+'0'.repeat(at-digits.length);let r=digits.slice(0,at)+'.'+digits.slice(at);return r.replace(/^0+(?=\d)/,'');}
function fmt(v){if(v===null||v===undefined)return '–';let [a,b='']=String(v).split('.');b=b.replace(/0+$/,'');return a.replace(/\B(?=(\d{3})+(?!\d))/g,'\u00a0')+(b?','+b:'');}
function fInput(v){return v==null?'':String(v).replace('.',',');}
function pill(text,color=''){return `<span class="pill ${color}"><i class="dot"></i>${esc(text)}</span>`;}
function statusPill(status){return status==='approved'?pill('Jóváhagyott','green'):status==='intake'?pill('Adatbekérés','amber'):pill('Tervezet','amber');}
function button(text,action,style='',extra='',ico=''){return `<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;}
async function api(path,options={}){
  const headers={...options.headers};if(options.method&&options.method!=='GET')headers['X-CSRF-Token']=S.csrf;
  if(options.body&&!(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  const response=await fetch('/api'+path,{...options,headers,credentials:'same-origin'});
  if(!response.ok){let d;try{d=await response.json();}catch{d={detail:'A kérés nem sikerült.'};}let message=typeof d.detail==='string'?d.detail:d.detail?.message||'A kérés nem teljesíthető.';if(d.errors)message+='\n'+d.errors.map(e=>e.field+': '+e.message).join('\n');const e=new Error(message);e.status=response.status;e.details=d;throw e;}
  return response.json();
}
function toast(text,error=false){const root=document.querySelector('#toast-root');while(root.children.length>=2)root.firstElementChild.remove();const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=text;document.querySelector('#toast-root').append(e);setTimeout(()=>e.remove(),error?8500:4500);}
function markDirty(){S.dirty=true;S.editRevision++;S.lastSave=null;refreshApprovalAvailability();document.querySelectorAll('[data-action="save"]').forEach(b=>b.disabled=false);const status=document.querySelector('#save-status');if(status)status.textContent='Újraszámítás szükséges · nem mentett módosítások';const notice=document.querySelector('#recalculation-notice');if(notice)notice.innerHTML=recalculationNotice();}
function modal(title,body,kind,context={},footer=''){
  S.modal={kind,...context};document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-button" data-action="close-modal" aria-label="Bezárás">${icon('close')}</button></div><form id="modal-form"><div class="modal-body"><p class="modal-error hide" id="modal-error"></p>${body}</div><div class="modal-footer">${footer||button('Mégse','close-modal')}<button class="btn primary" type="submit">${kind==='new'?'Vizsgálat létrehozása':kind==='user'?'Felhasználó létrehozása':'Mentés és újraszámítás'} ${icon('check')}</button></div></form></section></div>`;
  try{updateModalGuidance();}catch{}
  document.querySelector('.modal input:not([type=checkbox]),.modal select,.modal textarea')?.focus();
}
function closeModal(force=false){if(!force&&document.querySelector('#modal-form [type=submit]')?.disabled)return;document.querySelector('#modal-root').innerHTML='';S.modal=null;}
function field(label,name,value='',type='text',extra='',hint=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</div>`;}
function area(label,name,value='',extra=''){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;}
function select(label,name,value,options,extra=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
function check(label,name,value=false){return `<label class="checkbox"><input type="checkbox" name="${name}" ${value?'checked':''}><span>${label}</span></label>`;}
function companyOptions(){return S.data.companies.map(c=>[c.id,c.name]);}
function brand(){return `<div class="brand"><span class="brand-mark">${icon('network')}</span><div><strong>Kapcsolati műhely</strong><small>SZAKÉRTŐI MUNKATÉR</small></div></div>`;}
function heroGraphic(){return `<svg viewBox="0 0 360 190" aria-hidden="true"><path d="M80 53H180V137H276 M80 137H180 M180 53H276" fill="none" stroke="#8cc6d0" stroke-width="1.5"/><circle cx="180" cy="96" r="4" fill="#008ca6"/><rect x="14" y="30" width="116" height="46" rx="10" fill="#1c3658"/><text x="29" y="57" fill="white" font-size="11" font-family="DM Sans,Arial">Vizsgált cég</text><rect x="14" y="115" width="116" height="46" rx="10" fill="white" stroke="#e3eaee"/><text x="33" y="142" fill="#1c3658" font-size="11" font-family="DM Sans,Arial">Cégcsoport</text><rect x="230" y="30" width="116" height="46" rx="10" fill="#e1f3f5" stroke="#8cc6d0"/><text x="241" y="57" fill="#006474" font-size="10" font-family="DM Sans,Arial">Kapcsolódó · 100%</text><rect x="230" y="115" width="116" height="46" rx="10" fill="#eaf3fa" stroke="#b8cfe5"/><text x="254" y="142" fill="#1c3658" font-size="10" font-family="DM Sans,Arial">Partner · 50%</text></svg>`;}
function shell(content,breadcrumb='Ügyek'){
  const initials=S.user.name.split(' ').slice(0,2).map(n=>n[0]).join('');
  const mobileItems=S.page==='case'&&staff()?[
    ['overview','Áttekintés','grid'],['companies','Adatok','building'],['calculation','Eredmény','calculator'],['review','Ellenőrzés','shield']
  ].map(([tab,label,ico])=>button(`<span>${label}</span>`,'tab',S.tab===tab?'active':'',`data-tab="${tab}"`,ico)).join(''):
    `${button('Ügyek','dashboard',S.page==='dashboard'?'active':'','','grid')}<a href="/pdf-import?module=kkv">${icon('upload')}<span>PDF-import</span></a><a href="/tao">${icon('network')}<span>Tao</span></a>${staff()?button('Új ügy','new-case','','','plus'):button('Kilépés','logout','','','logout')}`;
  document.querySelector('#app').innerHTML=`<div class="shell"><header class="site-header"><div class="sidebar">${brand()}<nav class="main-navigation" aria-label="Fő navigáció">${button('Ügyek','dashboard',S.page==='dashboard'?'active':'','','grid')}${staff()?'<a class="btn" href="/pdf-import?module=kkv">'+icon('upload')+'PDF-import</a>':''}<a class="btn" href="/tao">${icon('network')}Tao-kapcsoltság</a></nav><details class="workspace-tools"><summary>Eszközök</summary><div class="tools-menu">${staff()?`${button('Új vizsgálat','new-case','','','plus')}${button('Adatbekérő sablon','template','','','file')}${button('Mintavizsgálat','demo','','','grid')}`:''}${S.user.role==='admin'?button('Munkatársak','users','','','users'):''}</div></details><div class="user-panel"><div class="avatar">${esc(initials)}</div><div class="account-name"><strong>${esc(S.user.name)}</strong><small>${roles[S.user.role]}</small></div><button class="icon-button" data-action="logout" aria-label="Kijelentkezés">${icon('logout')}</button></div></div></header><div class="workspace"><header class="topbar"><div class="topbar-title">Munkatér <span class="relationship-arrow">/</span> <strong>${esc(breadcrumb)}</strong></div><div class="search">${icon('search')}<input id="global-search" aria-label="Vizsgálatok keresése" placeholder="Keresés az ügyekben" value="${esc(S.search)}"><kbd>Ctrl K</kbd></div></header><main class="content" id="main-content">${content}</main></div><nav class="mobile-navigation" aria-label="Gyors navigáció">${mobileItems}</nav></div>`;
}

function renderAuth(setup){
  document.querySelector('#app').innerHTML=`<main class="auth-page"><section class="auth-brand">${brand()}<div><div class="eyebrow">KKV ÉS TAO · SZAKÉRTŐI ELLENŐRZÉS</div><h1>Egy cégháló.<br>Minden összefüggés.</h1><p>Cégadatok, KKV-minősítés és Tao-kapcsoltság, egy munkatérben.</p><div class="auth-visual">${heroGraphic()}</div></div><div class="auth-footer">Tesztverzió · Ellenőrizhető adatok · Szakértői jóváhagyás</div></section><section class="auth-form-area"><form class="auth-form" id="auth-form" data-setup="${setup}"><div class="mobile-brand">${brand()}</div><div class="eyebrow">${setup?'ELSŐ BELÉPÉS':'ÜDVÖZÖLJÜK A MUNKATÉRBEN'}</div><h2>${setup?'Hozza létre a munkaterét.':'Jó újra itt látni.'}</h2><p>${setup?'Állítsa be saját adminisztrátori fiókját. Ezzel kezelheti az ügyeket és a munkatársak hozzáférését.':'Jelentkezzen be, és folytassa a vizsgálatait.'}</p>${setup?field('Teljes név','name','','text','required minlength="2" autocomplete="name"'):''}${field('Felhasználónév','username','','text','required minlength="3" autocomplete="username"')}${field('Jelszó','password','','password',`required ${setup?'minlength="12"':''} autocomplete="${setup?'new-password':'current-password'}"`,setup?'Legalább 12 karakter. A jelszót csak Ön adja meg.':'')}<button class="btn primary" type="submit">${setup?'Munkatér létrehozása':'Bejelentkezés'} ${icon('arrow')}</button><div class="auth-error" id="auth-error" role="alert"></div><p class="small-text">${setup?'Az első fiók adminisztrátori és szakértői jóváhagyási jogosultságot kap. További munkatársakat belépés után vehet fel.':'A hozzáférést a munkatér adminisztrátora kezeli.'}</p></form></section></main>`;
}
function renderDashboard(){
  const filtered=S.cases.filter(c=>(c.title+' '+c.client+' '+c.label).toLowerCase().includes(S.search.toLowerCase()));
  const open=S.cases.filter(c=>c.status!=='approved').length,approved=S.cases.filter(c=>c.status==='approved').length;
  shell(`<div class="page-heading"><div><div class="eyebrow">${staff()?'KKV-MINŐSÍTÉS · TESZTVERZIÓ':'ÜGYFÉLMUNKATÉR'}</div><h1>${staff()?'Ügyeid, egy helyen.':'A vállalkozásod vizsgálatai.'}</h1><p>${staff()?'A céghálótól az indokolt állásfoglalásig.':'Adatbekérés, dokumentumok és jóváhagyott eredmények.'}</p></div>${staff()?`<div class="button-row"><a class="btn" href="/pdf-import?module=kkv">OPTEN PDF-import</a><a class="btn" href="/tao">Tao-kapcsoltság</a>${button('Excel import','import','','','upload')}${button('Új vizsgálat','new-case','primary','','plus')}</div>`:''}</div>${staff()?`<section class="hero"><div class="hero-copy"><div class="eyebrow">AZ ADATOK MÖGÖTT OTT A TELJES KÉP</div><h2>Összefüggésekből minősítés.</h2><p>Rögzítsd a vállalkozásokat, ellenőrizd a kapcsolataikat, és készíts indokolt KKV-állásfoglalást egyetlen munkafolyamatban.</p>${button('A mintavizsgálat megnyitása','demo','light','','arrow')}</div><div class="hero-graphic">${heroGraphic()}</div></section>`:''}<section class="stats"><div class="stat"><div><span class="stat-label">Összes vizsgálat</span><strong class="stat-number">${S.cases.length}</strong></div><span class="stat-icon">${icon('file')}</span></div><div class="stat"><div><span class="stat-label">Folyamatban</span><strong class="stat-number">${open}</strong></div><span class="stat-icon">${icon('clock')}</span></div><div class="stat"><div><span class="stat-label">Jóváhagyott</span><strong class="stat-number">${approved}</strong></div><span class="stat-icon">${icon('shield')}</span></div></section><div class="section-heading"><h2>Vizsgálatok</h2><small>${filtered.length} ügy</small></div><section class="card flush">${filtered.length?`<div class="table-wrap"><table><thead><tr><th>VIZSGÁLAT / ÜGYFÉL</th><th>IDŐSZAK</th><th>MINŐSÍTÉS</th><th>ÁLLAPOT</th><th></th></tr></thead><tbody>${filtered.map(c=>`<tr class="case-row" tabindex="0" role="link" data-action="open-case" data-id="${c.id}"><td><div class="case-name"><span class="case-emblem">${icon('building')}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.client||'Ügyfél még nincs megadva')} · ${shortDate(c.updated)}</small></div></div></td><td>${c.years.join(' / ')}</td><td>${pill(c.label,c.category?'dark':'')}</td><td>${statusPill(c.status)}${c.blockers?`<small class="muted" style="display:block;font-size:9px;margin-top:5px">${c.blockers} tisztázandó pont</small>`:''}</td><td>${icon('arrow')}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>A legutóbbi módosítás szerint rendezve</span><span>${staff()?'Jóváhagyás után átadható':'Csak az Ön ügyei láthatók'}</span></div>`:`<div class="empty">${icon('file')}<h3>${S.search?'Nincs egyező vizsgálat.':'Még nincs vizsgálat a munkatérben.'}</h3><p>${staff()?'Hozz létre egy ügyet, importáld a meglévő Excel-fájlt, vagy nézd meg a kitöltött mintavizsgálatot.':'Az adminisztrátor itt rendeli Önhöz a vizsgálatot.'}</p>${staff()?button('Új vizsgálat','new-case','primary','','plus'):''}</div>`}</section><div class="bottom-note">KKV műhely · Minden ügy mögött ellenőrizhető adatok és szakértői döntések.</div>`);
}
const tabs=[['overview','Áttekintés','grid'],['companies','Vállalkozások','building'],['graph','Cégháló','network'],['financials','Éves adatok','calculator'],['decisions','Kapcsolati döntések','users'],['calculation','Számítás','calculator'],['review','Ellenőrzés','shield'],['documents','Dokumentumok','file']];
function renderCase(){
  if(!S.data)return;
  const body={overview:overview,companies:companies,graph:graph,financials:financials,decisions:decisions,calculation:calculation,review:review,documents:documents}[S.tab]||overview;
  shell(`<button class="back-link" data-action="dashboard">${icon('back')} Vissza a vizsgálatokhoz</button><div class="page-heading case-heading"><div><div class="eyebrow">${esc(S.data.client||'KKV-VIZSGÁLAT')}</div><h1>${esc(company(S.data.root)?.name||S.data.title)}</h1><div class="case-meta">${statusPill(S.dirty?'draft':S.status)}<span>${S.data.years.join(' / ')}</span><span>·</span><span>${S.data.profile==='HU'?'Magyar Kkv. törvény':'EU KKV-definíció'}</span><span>·</span><span id="save-status">${S.dirty?'Újraszámítás szükséges · nem mentett módosítások':S.version+'. mentett verzió'}</span></div></div><div class="button-row">${button('Ügyadatok','case-settings','','','edit')}${button('Mentés','save','primary',S.dirty?'':'disabled','save')}</div></div><nav class="tabs" aria-label="Vizsgálat lépései">${tabs.map(([key,name,ico])=>`<button class="tab ${S.tab===key?'active':''}" data-action="tab" data-tab="${key}">${icon(ico)}${name}${key==='review'&&reviewChecks().length?`<span class="tab-badge">${groupedChecks(reviewChecks()).length}</span>`:''}</button>`).join('')}</nav>${caseFeedback()}<div id="recalculation-notice" aria-live="polite">${recalculationNotice()}</div><div id="case-body">${body()}</div>`,S.data.title);
  if(S.tab==='documents'){loadDocuments();loadReportPreview();}
  if(S.tab==='review'){S.pendingIntake=null;loadAudit();loadReviewIntake();refreshApprovalAvailability();}
}
function overview(){
  const last=S.calc.years.at(-1),tot=last?.totals||{},limit=250,percent=Math.min(100,Number(tot.employees||0)/limit*100);
  return `${S.calc.blockers.length?`<div class="banner amber">${icon('alert')}<div><strong>Előzetes eredmény · ${groupedChecks().length} rendezendő kérdés</strong><p>A véglegesítéshez ellenőrizd a forrásokat és a kapcsolati döntéseket. ${button('Ellenőrzések megnyitása','tab','ghost','data-tab="review"')}</p></div></div>`:`<div class="banner green">${icon('check')}<div><strong>A számítás ellenőrzési pontjai rendezettek.</strong><p>${S.status==='approved'?'Az állásfoglalás jóváhagyott verzióból készül.':'A vizsgálat szakértői jóváhagyásra előkészítve.'}</p></div></div>`}<div class="grid-main"><div class="stack"><section class="card result-card"><div class="eyebrow">TÖRTÉNETI SZABÁLY SZERINTI MINŐSÍTÉS</div><h2>${esc(S.calc.label)}</h2><p>${S.calc.ready?'A rögzített adatokból számított minősítés.':'Előzetes következtetés; a tisztázandó pontok rendezése szükséges.'}</p>${pill(S.status==='approved'?'Szakértőileg jóváhagyott':'Szakértői ellenőrzésre vár',S.status==='approved'?'green':'amber')}<div class="annual-grid">${S.calc.years.map(y=>`<div class="annual-block"><small>${y.year} · ÉVES MÉRET</small><strong>${esc(y.label)}</strong><small>${fmt(y.totals.employees)} fő · ${fmt(scale(y.totals.turnover,-3))} ezer Ft árbevétel</small></div>`).join('')}</div></section><section class="card"><div class="section-heading"><h2>Minősítési idővonal</h2>${button('Előzmények','case-settings','ghost','','clock')}</div><p class="small-text muted">Az éves méret és a hatályos kategória külön követhető.</p><div class="timeline">${S.calc.history.map(h=>`<div class="timeline-item"><strong>${h.year}</strong><span>${esc(labels[h.effective]||'Előzmény szükséges')}</span>${h.pending?'<em>Átmeneti megfigyelés</em>':''}</div>`).join('')}</div>${S.data.events.length?`<p class="section-note">${S.data.events.length} rögzített strukturális esemény.</p>`:''}</section></div><div class="stack"><section class="card"><div class="section-heading"><h2>Összesített mutatók</h2><small>${last?.year||''}</small></div><div class="metric-row"><span>Éves létszám</span><strong>${fmt(tot.employees)} fő</strong></div><div class="metric-bar"><b style="width:${percent}%"></b></div><div class="metric-labels"><span>0 fő</span><span>KKV-határ: &lt; 250 fő</span></div><div class="metric-row" style="margin-top:15px"><span>Árbevétel</span><strong>${fmt(scale(tot.turnover,-3))} ezer Ft</strong></div><div class="metric-row"><span>Mérlegfőösszeg</span><strong>${fmt(scale(tot.balance,-3))} ezer Ft</strong></div><div class="metric-row"><span>EUR/HUF</span><strong>${fmt(last?.rate)}</strong></div>${button('Részletes összeszámítás','tab','ghost','data-tab="calculation"','arrow')}</section><section class="card"><div class="section-heading"><h2>Következő lépések</h2></div><div class="checks">${checkCards(S.calc.blockers.slice(0,3))||`<div class="check-item">${icon('check')}<span>A forrás- és számítási ellenőrzések rendezettek.</span></div>`}<div class="check-item">${icon('file')}<span>Állásfoglalás előkészítése<small>A számítás aktuális mentett verziójából.</small></span></div></div>${button('Dokumentumok','tab','ghost','data-tab="documents"','arrow')}</section></div></div>`;
}
function companies(){
  return `<div class="section-heading"><div><h2>Vállalkozások</h2><small>A vizsgálat cégei és a kapcsolati háló szereplői.</small></div>${button('Vállalkozás felvétele','edit-company','primary','','plus')}</div><div class="companies-grid">${S.data.companies.map(c=>`<section class="card company-card"><div class="company-top"><div class="company-icon">${icon('building')}</div>${c.id===S.data.root?pill('Vizsgált cég','green'):pill(c.kind==='public'?'Közjogi szereplő':c.kind==='investor'?'Befektető':c.country)}</div><h3>${esc(c.name)}</h3><p class="company-state">${esc(companyState(c.id))}</p><p>${esc(c.activity||'Tevékenység még nincs megadva.')}</p><div class="company-footer"><span>${esc(c.registration||'Azonosító nincs rögzítve')}</span>${S.calc.blockers.some(b=>b.code==='relationship_missing'&&b.target===c.id)?button('Kapcsolat rendezése','resolve-check','small',`data-index="${S.calc.blockers.findIndex(b=>b.code==='relationship_missing'&&b.target===c.id)}" data-year="${S.year}"`):''}<button class="icon-button" data-action="edit-company" data-id="${esc(c.id)}" aria-label="${esc(c.name)} szerkesztése">${icon('edit')}</button></div></section>`).join('')}</div><div class="section-heading section-spacer"><div><h2>Természetes személyek</h2><small>A tulajdonosok és a közös fellépés vizsgálatának szereplői.</small></div>${button('Személy felvétele','edit-person','','','plus')}</div><div class="persons-grid">${S.data.persons.map(p=>`<div class="person-chip"><div class="avatar">${esc(p.name.slice(0,1))}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.notes.slice(0,45)||'Természetes személy')}</small></div><button class="icon-button right" data-action="edit-person" data-id="${esc(p.id)}" aria-label="Személy szerkesztése">${icon('edit')}</button></div>`).join('')||'<p class="small-text muted">Még nincs rögzített természetes személy.</p>'}</div>`;
}
function structureDay(){const f=S.data.financials.find(f=>f.company===S.data.root&&f.year===S.year),closing=f?.end||`${S.year}-12-31`;return S.data.structure_basis==='assessment'||(f?.estimated&&closing>S.data.as_of)?S.data.as_of:closing;}
function inPeriod(o,day){return (!o.start||o.start<=day)&&(!o.end||o.end>=day);}
function graphSvg(){return networkSvg();}
function graph(){return `<section class="card"><div class="graph-caption"><div><h2 style="margin-bottom:5px">Tulajdonosi és döntési háló</h2><div class="legend"><span><i></i>Tulajdon / szavazat</span><span><i class="dashed"></i>Kapcsolati döntés</span></div></div><div class="button-row">${yearSwitch()}${button('SVG letöltése','download-graph','small','data-kind="svg"','download')}${button('PNG letöltése','download-graph','small','data-kind="png"','download')}${button('Elrendezés mentése','save','small',S.dirty?'':'disabled','save')}${button('Automatikus elrendezés','reset-graph','small')}${button('Kapcsolat felvétele','edit-ownership','primary','','plus')}</div></div><div class="graph-wrap">${graphSvg()}</div><p class="graph-note">Hálóidőpont: ${esc(structureDay())}. Húzd a szereplőket a kívánt helyre; a nyilak velük mozognak. Kattintással szerkeszthetsz, a nyílbillentyűkkel is mozgathatsz. Az Elrendezés mentése az ügyben rögzíti a pozíciókat. A letöltés az aktuális elrendezést tartalmazza.</p></section><div class="grid-2 section-spacer"><section class="card"><div class="section-heading"><h2>Tulajdoni és irányítási kapcsolatok</h2></div>${S.data.ownerships.map(o=>`<div class="list-row"><div><strong>${esc(actorName(o.owner))}<span class="relationship-arrow">→</span>${esc(actorName(o.company))}</strong><small>Tőke: ${fmt(o.capital)}% · Szavazat: ${fmt(o.votes)}%${o.control?' · Meghatározó irányítás':''}${o.start?' · '+esc(o.start):''}</small></div><button class="icon-button" data-action="edit-ownership" data-id="${esc(o.id)}" aria-label="Tulajdoni kapcsolat szerkesztése">${icon('edit')}</button></div>`).join('')||'<p class="small-text muted">Még nincs tulajdoni kapcsolat.</p>'}</section><section class="card"><div class="section-heading"><h2>Rokonsági viszonyok</h2>${button('Új viszony','edit-family','small','','plus')}</div>${S.data.families.map(f=>`<div class="list-row"><div><strong>${esc(actorName(f.first))} – ${esc(actorName(f.second))}</strong><small>${esc(f.relationship)}</small>${familyImpact(f)}</div><button class="icon-button" data-action="edit-family" data-id="${esc(f.id)}" aria-label="Rokonsági viszony szerkesztése">${icon('edit')}</button></div>`).join('')||'<p class="small-text muted">Rögzítsd a releváns rokoni viszonyokat. A rokonság mellett a közös fellépést és a piaci kapcsolatot is értékelni kell.</p>'}</section></div>`;}
function financialFor(cid,year){let f=S.data.financials.find(f=>f.company===cid&&f.year===year);if(!f){f={company:cid,year,employees:null,turnover:null,balance:null,currency:'HUF',start:`${year}-01-01`,end:`${year}-12-31`,accepted:null,employment_method:'annual',source:'',consolidated:false,included:[],estimated:false,annualized:false};S.data.financials.push(f);}return f;}
function rateFor(year){let r=S.data.rates.find(r=>r.year===year);return r||null;}
function yearSwitch(){return `<div class="year-switch">${S.data.years.slice().sort().map(y=>`<button type="button" class="${S.year===y?'active':''}" data-action="year" data-year="${y}">${y}</button>`).join('')}</div>`;}
function financials(){
  const rate=rateFor(S.year),rows=S.data.companies.filter(c=>c.kind!=='public');
  return `<div class="section-heading"><div><h2>Éves beszámolóadatok</h2><small>A pénzügyi mezők ezer egységben szerepelnek. A számítás teljes pontossággal történik.</small></div>${yearSwitch()}</div><section class="card flush"><div class="table-wrap"><table class="financial-table"><thead><tr><th>VÁLLALKOZÁS</th><th>LÉTSZÁM</th><th>ÁRBEVÉTEL (EZER)</th><th>MÉRLEG (EZER)</th><th>DEVIZA</th><th>ELFOGADÁS</th><th>FORRÁS</th><th></th></tr></thead><tbody>${rows.map(c=>{const f=S.data.financials.find(f=>f.company===c.id&&f.year===S.year)||{};return `<tr><td><strong>${esc(c.name)}</strong>${f.consolidated?'<small class="muted" style="display:block">Konszolidált adat</small>':''}</td>${['employees','turnover','balance'].map(k=>`<td><input aria-label="${esc(c.name)} ${k==='employees'?'létszám':k==='turnover'?'árbevétel':'mérleg'}" inputmode="decimal" data-fin="${k}" data-id="${esc(c.id)}" value="${esc(fInput(k==='employees'?f[k]:scale(f[k],-3)))}" placeholder="Hiányzik"></td>`).join('')}<td><select data-fin="currency" data-id="${esc(c.id)}" aria-label="Pénznem"><option ${f.currency!=='EUR'?'selected':''}>HUF</option><option ${f.currency==='EUR'?'selected':''}>EUR</option></select></td><td><input type="date" data-fin="accepted" data-id="${esc(c.id)}" aria-label="Beszámoló elfogadása" value="${esc(f.accepted||'')}"></td><td><input class="source-input" data-fin="source" data-id="${esc(c.id)}" aria-label="Beszámoló forrása" value="${esc(f.source||'')}" placeholder="Beszámoló / dokumentum"></td><td><button class="icon-button" data-action="edit-financial" data-id="${esc(c.id)}" aria-label="Beszámoló részletei">${icon('edit')}</button></td></tr>`;}).join('')}</tbody></table></div></section><section class="card rate-card"><div class="section-heading"><div><h2>MNB deviza-középárfolyam</h2><small>${S.year} · a releváns zárónapon érvényes HUF/EUR</small></div>${button('MNB-lekérés','mnb','small','','download')}</div><div class="rate-grid"><div class="field"><label>Érvényesség napja</label><input type="date" data-rate="date" aria-label="Árfolyam érvényessége" value="${esc(rate?.date||`${S.year}-12-31`)}"></div><div class="field"><label>Jegyzés napja</label><input type="date" data-rate="quoted" aria-label="MNB jegyzés napja" value="${esc(rate?.quoted||'')}"></div><div class="field"><label>HUF / EUR</label><input data-rate="value" aria-label="HUF EUR árfolyam" inputmode="decimal" placeholder="Például: 410,09" value="${esc(fInput(rate?.value))}"></div><div class="field"><label>Hivatalos forrás</label><input data-rate="source" aria-label="Árfolyam forrása" value="${esc(rate?.source||'')}" placeholder="MNB dokumentum vagy hivatkozás"></div></div><div class="rate-footer"><label class="checkbox"><input type="checkbox" data-rate="confirmed" ${rate?.confirmed?'checked':''}><span>A dátumot, árfolyamot és forrást ellenőriztem.</span></label><span class="small-text muted">Automatikus lekérés vagy dokumentált kézi rögzítés.</span></div></section><p class="section-note">Eltérő üzleti év, éves munkaegység, becslés és konszolidált adatok a sor végén lévő szerkesztőben adhatók meg.</p>`;
}
function decisions(){return `${checkCards(S.calc.blockers.filter(b=>['new_decision','decision','override','decisions'].includes(b.destination)))}<div class="section-heading"><div><h2>Kapcsolati döntések</h2><small>A tulajdoni adatokból levezetett kapcsolatok mellett a szakértői megállapítások.</small></div>${button('Új döntés','edit-decision','primary','','plus')}</div><div class="decision-grid">${S.data.decisions.map(d=>`<section class="card decision-card"><div><div class="decision-top">${pill(relationLabels[d.relation],d.relation==='linked'?'green':d.relation==='partner'?'dark':'')}${decisionNeeds(d).length?pill('Teendő: '+decisionNeeds(d).join(', '),'amber'):pill('Ellenőrzött','green')}${d.relation==='partner'?`<span class="small-text muted">${fmt(d.percent)}% beszámítás</span>`:''}</div><h3>${esc(actorName(d.first))}<span class="relationship-arrow">↔</span>${esc(actorName(d.second))}</h3><p class="reason">${esc(d.reason||'Az indoklás még nincs megadva.')}</p>${d.basis==='persons'?`<p>Közös fellépés: ${esc(d.acting_together||'tisztázandó')}<br>Piac: ${esc(d.market||'tisztázandó')}</p>`:''}<small class="muted">Forrás: ${esc(d.source||'hiányzik')}</small></div><div class="button-row">${button('Döntés szerkesztése','edit-decision','small',`data-id="${esc(d.id)}"`,'edit')}</div></section>`).join('')||`<div class="card empty">${icon('users')}<h3>Rögzítsd a szakértői megállapításokat.</h3><p>Természetes személyeken keresztüli kapcsolatnál add meg a közös fellépés és a piaci viszony indoklását. A kizárt cégek önálló minősítését is dokumentáld.</p></div>`}</div><section class="card section-spacer"><div class="section-heading"><h2>Összeszámítási felülbírálatok</h2>${button('Új döntés','edit-override','small','','plus')}</div><p class="small-text muted">Több partnerútvonal esetén a kapcsolódó adatblokk végső aránya itt rögzíthető, indoklással.</p>${S.data.overrides.map(o=>`<div class="list-row"><div><strong>${o.year} · ${esc(actorName(o.company))} · ${fmt(o.percent)}%</strong><small>${esc(o.reason)}</small></div>${button('Szerkesztés','edit-override','small',`data-id="${esc(o.company)}" data-year="${o.year}"`)}</div>`).join('')}</section>`;}
function calculation(){
  const calc=S.scenario==='all'&&S.scenarioCalc?S.scenarioCalc:S.calc,y=calc.years.find(y=>y.year===S.year)||calc.years.at(-1);
  return `<div class="calculation-summary"><div><div class="eyebrow">${S.scenario==='all'?'ÉRZÉKENYSÉGVIZSGÁLAT':'ELLENŐRIZHETŐ ÖSSZESZÁMÍTÁS'}</div><h2>${esc(y?.label||'Hiányos adatok')}</h2><span class="small-text muted">${S.scenario==='all'?'Minden ismert üzleti vállalkozás 100%-ban; önálló jogi minősítésként nem véglegesíthető.':'Minden beszámítási tétel jogcímmel és indoklással.'}</span></div><div class="button-row"><select class="form-inline-select" id="scenario" aria-label="Számítási forgatókönyv"><option value="base" ${S.scenario==='base'?'selected':''}>Alapforgatókönyv</option><option value="all" ${S.scenario==='all'?'selected':''}>Minden cég 100%-ban</option></select>${yearSwitch()}</div></div>${calculationCompleteness(calc,y)}<section class="card flush"><div class="table-wrap"><table class="calculation-table"><thead><tr><th>VÁLLALKOZÁS</th><th>JOGCÍM</th><th>ARÁNY</th><th>LÉTSZÁM</th><th>ÁRBEVÉTEL (EZER FT)</th><th>MÉRLEG (EZER FT)</th><th>INDOK</th></tr></thead><tbody>${y?.rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${pill(relationLabels[r.relation],r.relation==='own'||r.relation==='linked'?'green':'')}</td><td class="number">${fmt(r.percent)}%</td><td class="number">${fmt(r.employees)}</td><td class="number">${fmt(scale(r.turnover,-3))}</td><td class="number">${fmt(scale(r.balance,-3))}</td><td class="reason-cell">${esc(r.reason)}</td></tr>`).join('')||''}<tr class="calculation-total"><td>${y?.complete?'Összesen':'Összesen · ismert adatokból'}</td><td></td><td></td><td class="number">${fmt(y?.totals.employees)}</td><td class="number">${fmt(scale(y?.totals.turnover,-3))}</td><td class="number">${fmt(scale(y?.totals.balance,-3))}</td><td>${y?.complete?'Teljes számszerű adatkör':'Hiányos számszerű adatkör'}</td></tr></tbody></table></div></section><div class="grid-2 section-spacer"><section class="card"><h2>Alkalmazott korlátok</h2><div class="table-wrap"><table><thead><tr><th>Kategória</th><th>Létszám</th><th>Árbevétel EUR</th><th>Mérleg EUR</th></tr></thead><tbody><tr><td>Mikro</td><td>&lt; 10</td><td>≤ 2 millió</td><td>≤ 2 millió</td></tr><tr><td>Kis</td><td>&lt; 50</td><td>≤ 10 millió</td><td>≤ 10 millió</td></tr><tr><td>Közép</td><td>&lt; 250</td><td>≤ 50 millió</td><td>≤ 43 millió</td></tr></tbody></table></div><p class="section-note">Létszám ÉS (árbevétel VAGY mérlegfőösszeg). A pénzügyi határérték megengedett, a létszámhatár szigorú.</p></section><section class="card"><h2>A minősítés következménye</h2><p class="small-text">${esc(calc.transfer_pricing)}</p><p class="section-note">A konkrét adóévi kapcsolt ügyletek és mentességek külön vizsgálatot igényelnek.</p></section></div>`;
}
function review(){return `<div class="grid-main"><div class="stack"><section class="card"><div class="section-heading"><h2>Véglegesítés előtti ellenőrzések</h2>${pill(groupedChecks(reviewChecks()).length+' rendezendő kérdés',reviewChecks().length?'amber':'green')}</div><div class="review-controls">${yearSwitch()}<select id="review-scope" aria-label="Ellenőrzések köre"><option value="year" ${S.reviewScope!=='all'?'selected':''}>Csak ${S.year}. év</option><option value="all" ${S.reviewScope==='all'?'selected':''}>Minden vizsgált év</option></select></div>${checkSummary()}<div class="year-check-counts">${S.data.years.map(y=>button(y+': '+groupedChecks(S.calc.blockers.filter(b=>!b.year||b.year===y)).length+' teendő','review-year','small',`data-year="${y}"`)).join('')}</div>${checkCards(reviewChecks())||'<div class="check-item">'+icon('check')+'<span>Nincs nyitott számítási vagy adatellenőrzési pont.</span></div>'}</section><section class="card"><h2>Feldolgozandó ügyfélválaszok</h2><p class="small-text muted">A választ olvasd el, a szükséges adatokat vezesd át, majd jelöld feldolgozottnak.</p><div id="review-intake-panel">Betöltés…</div></section><section class="card"><div class="section-heading"><h2>Strukturális események</h2>${button('Esemény felvétele','edit-event','small','','plus')}</div><p class="small-text muted">Alapítás, irányításváltás vagy felvásárlás esetén a történeti szabály kezelését is indokolni kell.</p>${S.data.events.map(e=>`<div class="list-row"><div><strong>${esc(e.date)} · ${esc(e.description)}</strong><small>${esc(e.resolution||'Szakértői kezelés még nincs rögzítve.')}</small></div>${button('Szerkesztés','edit-event','small',`data-id="${esc(e.id)}"`)}</div>`).join('')}</section><section class="card"><div class="section-heading"><h2>Közjogi részesedés</h2>${button('Vizsgálat rögzítése','edit-public','small','','edit')}</div><p class="small-text muted">Összesített közvetlen és közvetett állami / önkormányzati részesedés.</p><div class="metric-row"><span>Tőke / szavazat</span><strong>${fmt(S.data.public_review.capital)}% / ${fmt(S.data.public_review.votes)}%</strong></div><p class="small-text">${esc(S.data.public_review.reason||'Közjogi szereplő rögzítése esetén külön szakértői összesítés szükséges.')}</p></section></div><div class="stack"><section class="card approval-card"><div class="eyebrow">SZAKÉRTŐI JÓVÁHAGYÁS</div><h2 style="margin-top:12px">A végleges állásfoglalás alapja.</h2><p class="small-text muted">A jóváhagyás a mentett verzió adatait és számítását rögzíti. Módosítás után új verzió készül.</p>${S.status==='approved'?`<div class="banner green">${icon('shield')}<strong>Ez a verzió jóváhagyott.</strong></div>${button('Állásfoglalás megnyitása','tab','primary','data-tab="documents"','file')}`:`<form id="approval-form">${field('Ellenőrzött jogi időállapot','law_date',S.data.law_date||'','date','readonly')}${button('Jogi források rögzítése','case-settings')}<p id="approval-progress" class="section-note" role="status"></p>${check('A beszámolókat, létszámadatokat és árfolyamforrásokat ellenőriztem.','financials')}${check('A kapcsolati döntéseket, irányítást és releváns piaci viszonyokat ellenőriztem.','relationships')}${check('Az alkalmazandó jogszabályi időállapotot, szabályokat és kivételeket szakértőként ellenőriztem.','rules')}${area('Jóváhagyási megjegyzés','note')}<button type="submit" class="btn primary" ${!canApprove()||!S.calc.ready||S.dirty?'disabled':''}>${icon('shield')} Jóváhagyás és véglegesítés</button>${!canApprove()?'<p class="section-note">Jóváhagyó szakértői vagy adminisztrátori szerepkör szükséges.</p>':''}</form>`}</section><section class="card"><div class="section-heading"><h2>Verziók és változásnapló</h2></div><div id="audit-panel" class="small-text muted">Betöltés…</div></section></div></div>`;}
function documents(){return `<div class="section-heading"><div><h2>Állásfoglalás és forrásdokumentumok</h2><small>${S.status==='approved'?'Jóváhagyott dokumentumok a lezárt számításból.':'Az export egyértelműen tervezetként készül.'}</small></div><div class="button-row">${button('Word '+(S.status==='approved'?'letöltése':'tervezet'),'export','','data-kind="docx"','download')}${button('PDF '+(S.status==='approved'?'letöltése':'tervezet'),'export','primary','data-kind="pdf"','download')}</div></div><div class="grid-main"><section class="report-preview"><div class="eyebrow">${S.status==='approved'?'ÁLLÁSFOGLALÁS':'TERVEZET · JÓVÁHAGYÁSRA VÁR'}</div><h2>${esc(company(S.data.root)?.name)}</h2><div class="report-meta">KKV-minősítés · ${esc(S.data.as_of)} · ${S.version}. verzió</div><div id="report-preview-content" aria-live="polite">A mentett állásfoglalás előnézetének betöltése…</div></section><div class="stack"><section class="card"><h2>Forrásdokumentumok</h2><div class="upload-zone" data-action="upload">${icon('upload')}<p>Dokumentum feltöltése</p><small>PDF, Word, Excel vagy kép · legfeljebb 20 MB</small></div><div id="documents-panel"><p class="section-note">Betöltés…</p></div></section><section class="card"><h2>Ügyfélválaszok</h2><div id="intake-panel"><p class="section-note">Betöltés…</p></div></section></div></div>`;}
async function loadDocuments(){
  const cid=S.cid;try{const [docs,intakes]=await Promise.all([api(`/cases/${cid}/documents`),api(`/cases/${cid}/intake`)]);if(cid!==S.cid)return;const panel=document.querySelector('#documents-panel');if(panel)panel.innerHTML=docs.map(d=>`<div class="document-row"><span class="document-icon">${icon('file')}</span><div><strong>${esc(d.filename)}</strong><small>${fmt(Math.ceil(d.size/1024))} KB · ${shortDate(d.created)}</small><span class="source-code" title="${esc(d.sha256)}">SHA-256: ${d.sha256.slice(0,16)}…</span></div><a class="btn small" href="/api/cases/${cid}/documents/${d.id}" aria-label="Dokumentum letöltése">${icon('download')}</a></div>`).join('')||'<p class="section-note">Még nincs feltöltött dokumentum.</p>';const ip=document.querySelector('#intake-panel');if(ip)ip.innerHTML=intakes.map(i=>`<div class="list-row" style="display:block"><small class="muted">${esc(i.author)} · ${shortDate(i.created)}</small><div class="intake-message">${esc(i.message)}</div><div class="button-row" style="margin-top:10px">${i.reviewed?pill('Feldolgozott','green'):staff()?button('Feldolgozottként jelölés','review-intake','small',`data-id="${i.id}"`):pill('Ellenőrzésre vár','amber')}</div></div>`).join('')||'<p class="section-note">Még nincs beküldött ügyfélválasz.</p>';}catch(e){toast(e.message,true);}
}
async function loadAudit(){try{const [audit,versions]=await Promise.all([api(`/cases/${S.cid}/audit`),api(`/cases/${S.cid}/versions`)]);const el=document.querySelector('#audit-panel');if(!el)return;el.innerHTML=`<div>${versions.slice(0,5).map(v=>`<div class="list-row"><div><strong>${v.version}. verzió ${v.approved_at?'· jóváhagyott':''}</strong><small>${esc(v.author)} · ${shortDate(v.created)}</small></div>${button('Megnyitás','view-version','small',`data-version="${v.version}"`)}</div>`).join('')}</div><ul class="audit-list">${audit.slice(0,8).map(a=>`<li>${esc(a.details||a.action)}<small>${esc(a.actor||'Rendszer')} · ${shortDate(a.created)}</small></li>`).join('')}</ul>`;}catch(e){toast(e.message,true);}}
function renderClientCase(d){shell(`<button class="back-link" data-action="dashboard">${icon('back')} Vissza a vizsgálatokhoz</button><section class="client-intro"><div class="eyebrow">AZ ÖN VIZSGÁLATA</div><h2>${esc(d.title)}</h2><p>${esc(d.purpose)}</p>${statusPill(d.status)}${d.label?` <span class="pill">${esc(d.label)}</span>`:''}</section><div class="grid-2"><section class="card"><h2>Dokumentumok és eredmény</h2>${d.status==='approved'?`<p class="small-text muted">Jóváhagyott állásfoglalás · ${d.version}. verzió.</p><div class="button-row">${button('Word letöltése','client-export','','data-kind="docx"','download')}${button('PDF letöltése','client-export','primary','data-kind="pdf"','download')}</div>`:'<p class="small-text muted">A vizsgálat folyamatban van. A szakértői jóváhagyás után itt tölthető le az állásfoglalás.</p>'}<div class="section-spacer upload-zone" data-action="upload">${icon('upload')}<p>Beszámoló vagy igazoló dokumentum feltöltése</p><small>PDF, Word, Excel vagy kép · legfeljebb 20 MB</small></div><div id="documents-panel"></div></section><section class="card"><h2>Adatbekérés</h2><p class="small-text muted">Adja meg a tulajdonosokat, tulajdoni és szavazati arányokat, releváns rokoni kapcsolatokat, tevékenységeket és az esetleges változásokat. A beszámolókat csatolja a dokumentumoknál.</p><form id="intake-form">${area('Adatok és kiegészítések','message','','required minlength="5"')}<button class="btn primary" type="submit">${icon('upload')} Válasz beküldése</button></form><div id="intake-panel" class="section-spacer"></div></section></div>`,d.title);loadDocuments();}
function renderUsers(){shell(`<div class="page-heading"><div><div class="eyebrow">HOZZÁFÉRÉSEK</div><h1>Munkatársak és ügyfelek.</h1><p>Minden felhasználó a szerepkörének megfelelő munkafolyamatot látja.</p></div>${button('Felhasználó felvétele','new-user','primary','','plus')}</div><section class="card flush"><div class="table-wrap"><table class="admin-table"><thead><tr><th>NÉV</th><th>FELHASZNÁLÓNÉV</th><th>SZEREPKÖR</th><th>ÁLLAPOT</th></tr></thead><tbody>${S.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${pill(roles[u.role],'dark')}</td><td>${pill(u.active?'Aktív':'Inaktív',u.active?'green':'')}</td></tr>`).join('')}</tbody></table></div></section><p class="section-note">Az ügyfélfiók az ügy adatlapján rendelhető a megfelelő vizsgálathoz. Az ügyfél kizárólag a hozzá rendelt ügyeket és jóváhagyott eredményeket látja.</p>`,'Munkatársak');}
async function save(){
  if(S.invalid.size)throw Error('Egy számező formátuma hibás. Javítsa a kijelölt adatot a mentés előtt.');
  if(S.saving){await S.saving;if(S.dirty)return save();return;}
  if(!S.dirty)return;
  const cid=S.cid,revision=S.editRevision,before=S.calc;
  const data=structuredClone(S.data),version=S.version;
  S.saving=(async()=>{
    const result=await api(`/cases/${cid}`,{method:'PUT',body:{data,version,client_user_id:S.clientUserId||null}});
    if(S.cid!==cid)return;
    S.version=result.version;S.calc=result.calculation;S.status=result.status;
    S.dirty=S.editRevision!==revision;S.scenarioCalc=null;S.scenario='base';
    S.lastSave=saveFeedback(before,result.calculation);renderCase();toast(S.lastSave.text);
  })();
  try{await S.saving;}finally{S.saving=null;}
}
function openSettings(){const d=S.data;modal('A vizsgálat adatai',`<div class="form-grid">${field('Ügy megnevezése','title',d.title,'text','required')}${field('Ügyfél / megbízó','client',d.client)}${field('Vizsgálat időpontja','as_of',d.as_of,'date','required')}${field('Vizsgált évek','years',d.years.join(', '),'text','required','Évek vesszővel elválasztva, például: 2024, 2025')}${field('Ellenőrzött jogi időállapot','law_date',d.law_date||'','date')}${area('Jogi források és a vizsgált évekre vonatkozó hivatkozások','law_source',d.law_source||'')}${area('Történeti alkalmazhatóság indoka, ha eltérő időállapotból dolgozunk','law_applicability',d.law_applicability||'')}${select('Vizsgált vállalkozás','root',d.root,companyOptions())}${select('Jogi profil','profile',d.profile,[['HU','Magyar Kkv. törvény'],['EU','EU KKV-definíció']])}${select('Cégháló időpontja','structure_basis',d.structure_basis||'period_end',[['period_end','Évenként az üzleti év zárónapja'],['assessment','A vizsgálat napja']])}${select('Korábbi minősítés','previous_category',d.previous_category||'',[['','Nincs ismert előzmény'],...Object.entries(labels).filter(([k])=>k!=='public')])}${field('Korábbi minősítés referenciaideje','previous_date',d.previous_date||'','date')}${select('Hozzárendelt ügyfélfiók','client_user_id',S.clientUserId||'',[['','Nincs ügyfélfiók'],...S.users.filter(u=>u.role==='client').map(u=>[u.id,u.name])])}${area('Vizsgálat célja','purpose',d.purpose)}${area('Feltételezések és korlátozások','assumptions',d.assumptions)}${area('Kiegészítő következtetés','conclusion_notes',d.conclusion_notes)}</div>`,'settings');}
