function financialModal(cid){const f=financialFor(cid,S.year);modal(`${actorName(cid)} · ${S.year}`,`<div class="form-grid">${field('Időszak kezdete','start',f.start||'','date')}${field('Időszak vége','end',f.end||'','date')}${field('Elfogadás napja','accepted',f.accepted||'','date')}${select('Létszámmódszer','employment_method',f.employment_method,[['annual','Éves jogszabályi létszám'],['AWU','Éves munkaegység (AWU)'],['estimate','Becsült éves létszám']])}${area('Adatforrás / évesítés indoka','source',f.source)}${select('Konszolidált adat','consolidated',String(f.consolidated),[['false','Egyedi beszámoló'],['true','Konszolidált beszámoló']])}<div class="field full"><label>Ebben az adatban már szereplő vállalkozások</label><div>${S.data.companies.filter(c=>c.id!==cid).map(c=>check(esc(c.name),'included-'+c.id,f.included.includes(c.id))).join('')}</div></div></div>${check('Lezárt beszámoló helyett új vállalkozás évesített becslése.','estimated',f.estimated)}${check('A rövid időszak / becslés évesítését elvégeztük és dokumentáltuk.','annualized',f.annualized)}`,'financial',{id:cid,year:S.year});}
function eventModal(itemId){const d=S.data.events.find(x=>x.id===itemId)||{};modal('Strukturális esemény',`<div class="form-grid">${field('Esemény időpontja','date',d.date||today(),'date','required')}${select('Esemény típusa','kind',d.kind||'control',[['control','Irányításváltozás'],['acquisition','Felvásárlás'],['founding','Alapítás'],['merger','Egyesülés'],['split','Szétválás'],['other','Egyéb']])}${area('Mi történt?','description',d.description||'','required')}${area('A minősítésre gyakorolt hatás és jogi indoka','resolution',d.resolution||'')}</div>${check('Az esemény hatását szakértőileg ellenőriztük.','confirmed',d.confirmed)}${check('Indokolt azonnali kategóriaváltás; erre az eseményre nem alkalmazzuk a két éves várakozást.','immediate',d.immediate)}`,'event',{id:itemId},(d.id?button('Eltávolítás','delete-item','danger',`data-list="events" data-id="${esc(d.id)}"`):'')+button('Mégse','close-modal'));}
function overrideModal(cid,year){const d=S.data.overrides.find(o=>o.company===cid&&o.year===Number(year))||{};modal('Összeszámítási döntés',`<p class="modal-intro">A kiválasztott vállalkozás teljes kapcsolódó adatblokkjára alkalmazott arány. Több partnerútvonal esetén jogi indoklás szükséges.</p><div class="form-grid">${select('Cég / adatblokk','company',d.company||cid||S.data.companies.find(c=>c.id!==S.data.root)?.id||S.data.root,companyOptions())}${select('Év','year',d.year||S.year,S.data.years.map(y=>[y,y]))}${field('Végső beszámítási arány (%)','percent',fInput(d.percent||0),'text','required inputmode="decimal"')}${area('A döntés indoka','reason',d.reason||'','required')}</div>${check('Az összeszámítási arányt szakértőileg ellenőriztem.','confirmed',d.confirmed)}`,'override',{id:cid,year:Number(year)},(d.company?button('Eltávolítás','delete-override','danger',`data-id="${esc(d.company)}" data-year="${d.year}"`):'')+button('Mégse','close-modal'));}
function publicModal(){const d=S.data.public_review;modal('Közjogi részesedés összesítése',`<p class="modal-intro">A teljes közvetlen és közvetett részesedést add meg. A magyar és EU-profil pontos határszövegét és a kivételeket a szakértő ellenőrzi.</p><div class="form-grid">${field('Összesített tőkerészesedés (%)','capital',fInput(d.capital),'text','required inputmode="decimal"')}${field('Összesített szavazati arány (%)','votes',fInput(d.votes),'text','required inputmode="decimal"')}${area('Tényállás, forrás és jogi indok','reason',d.reason)}</div>${check('Az adott jogi profil szerinti kivétel igazolt.','exception',d.exception)}${check('Az összesítést és a jogi következtetést ellenőriztem.','confirmed',d.confirmed)}`,'public');}
function upsert(list,item){const i=list.findIndex(x=>x.id===item.id);if(i===-1)list.push(item);else list[i]=item;}
async function submitModal(form){
  const p=Object.fromEntries(new FormData(form)),m=S.modal,bool=(name)=>form.elements[name]?.checked||false,nullable=(v)=>v||null;
  if(m.kind==='new'){
    const years=p.years.split(',').map(y=>Number(y.trim())).filter(Boolean);if(!years.length||years.some(y=>y<1990||y>2100))throw Error('Érvényes vizsgált éveket adj meg.');
    const cid=id(),data={title:p.title||p.name+' · KKV-vizsgálat',client:p.client,purpose:'KKV-minősítés',as_of:p.as_of,profile:p.profile,root:cid,years,companies:[{id:cid,name:p.name}],persons:[],ownerships:[],families:[],decisions:[],financials:[],rates:[],events:[],overrides:[],public_review:{capital:'0',votes:'0',exception:false,reason:'',confirmed:false},assumptions:'',conclusion_notes:''};
    const r=await api('/cases',{method:'POST',body:{data}});closeModal(true);location.hash=`case/${r.id}/overview`;return;
  }
  if(m.kind==='user'){await api('/users',{method:'POST',body:p});S.users=await api('/users');closeModal(true);renderUsers();toast('A felhasználó létrejött.');return;}
  const before={data:structuredClone(S.data),dirty:S.dirty,year:S.year,clientUserId:S.clientUserId};
  try{
  if(['company','person','ownership','family','decision','event'].includes(m.kind)&&!m.id)m.id=id();
  if(m.kind==='restore')S.data=structuredClone(m.snapshot.data);
  else if(m.kind==='settings'){
    const years=p.years.split(',').map(y=>Number(y.trim())).filter(Boolean);if(!years.length)throw Error('Legalább egy vizsgált év szükséges.');
    Object.assign(S.data,{title:p.title,client:p.client,as_of:p.as_of,law_date:nullable(p.law_date),law_source:p.law_source,law_applicability:p.law_applicability,years,root:p.root,profile:p.profile,structure_basis:p.structure_basis,previous_category:nullable(p.previous_category),previous_date:nullable(p.previous_date),purpose:p.purpose,assumptions:p.assumptions,conclusion_notes:p.conclusion_notes});S.data.decisions.forEach(d=>{if(d.confirmed_years!=null){d.confirmed_years=d.confirmed_years.filter(y=>years.includes(y));d.confirmed=d.confirmed&&d.confirmed_years.length>0;}});S.clientUserId=p.client_user_id||null;S.year=Math.max(...years);
  }else if(m.kind==='company')upsert(S.data.companies,{id:m.id||id(),name:p.name,registration:p.registration,country:p.country||'HU',kind:p.kind,activity:p.activity,founded:nullable(p.founded),ceased:nullable(p.ceased),investor_exception:bool('investor_exception'),exception_reason:p.exception_reason});
  else if(m.kind==='person')upsert(S.data.persons,{id:m.id||id(),name:p.name,notes:p.notes});
  else if(m.kind==='ownership'){if(p.owner===p.company)throw Error('Önmagára mutató kapcsolat nem adható meg.');upsert(S.data.ownerships,{...p,id:m.id||id(),capital:decimal(p.capital),votes:decimal(p.votes),start:nullable(p.start),end:nullable(p.end),control:bool('control')});}
  else if(m.kind==='family'){if(p.first===p.second)throw Error('Két külön személy szükséges.');upsert(S.data.families,{...p,id:m.id||id()});}
  else if(m.kind==='decision'){
    if(p.first===p.second)throw Error('Két külön vállalkozás szükséges.');
    const previous=S.data.decisions.find(d=>d.id===m.id),unchanged=previous&&['first','second','relation','basis','reason','source','market','acting_together','start','end'].every(k=>String(previous[k]??'')===String(p[k]??''))&&(p.relation!=='partner'||String(previous.percent)===decimal(p.percent));
    const checked=unchanged&&previous.confirmed?(previous.confirmed_years??S.data.years):[];
    const years=bool('all_years')?S.data.years:bool('confirmed')?[...new Set([...checked,m.year])]:checked.filter(y=>y!==m.year);
    upsert(S.data.decisions,{id:m.id,first:p.first,second:p.second,relation:p.relation,basis:p.basis,reason:p.reason,source:p.source,market:p.market,acting_together:p.acting_together,percent:p.relation==='partner'?decimal(p.percent):'0',confirmed:years.length>0,confirmed_years:years,start:nullable(p.start),end:nullable(p.end)});
  }
  else if(m.kind==='financial'){const f=financialFor(m.id,m.year);Object.assign(f,{start:nullable(p.start),end:nullable(p.end),accepted:nullable(p.accepted),employment_method:p.employment_method,source:p.source,consolidated:p.consolidated==='true',included:p.consolidated==='true'?S.data.companies.filter(c=>bool('included-'+c.id)).map(c=>c.id):[],estimated:bool('estimated'),annualized:bool('annualized')});}
  else if(m.kind==='event')upsert(S.data.events,{...p,id:m.id||id(),confirmed:bool('confirmed'),immediate:bool('immediate')});
  else if(m.kind==='override'){const item={company:p.company,year:Number(p.year),percent:decimal(p.percent),reason:p.reason,confirmed:bool('confirmed')};const i=S.data.overrides.findIndex(o=>o.company===m.id&&o.year===m.year);if(i>=0)S.data.overrides.splice(i,1);S.data.overrides.push(item);}
  else if(m.kind==='public')S.data.public_review={capital:decimal(p.capital),votes:decimal(p.votes),exception:bool('exception'),confirmed:bool('confirmed'),reason:p.reason};
  markDirty();await save();closeModal(true);
  }catch(error){S.data=before.data;S.dirty=before.dirty;S.year=before.year;S.clientUserId=before.clientUserId;renderCase();throw error;}
}
async function download(path,filename,buttonEl){
  if(buttonEl){buttonEl.disabled=true;buttonEl.dataset.original=buttonEl.innerHTML;buttonEl.innerHTML='<span class="spinner"></span> Előkészítés…';}
  try{const r=await fetch('/api'+path,{credentials:'same-origin'});if(!r.ok){const d=await r.json();throw Error(d.detail||'Az export nem sikerült.');}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('A dokumentum elkészült.');}finally{if(buttonEl&&buttonEl.isConnected){buttonEl.innerHTML=buttonEl.dataset.original;buttonEl.disabled=false;}}
}
function chooseFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',async()=>{if(!input.files[0])return;try{await callback(input.files[0]);}catch(e){toast(e.message,true);}});input.click();}
async function route(){
  const h=location.hash.slice(1),parts=h.split('/');
  if(S.dirty&&parts[0]!=='case'&&S.page==='case'){if(!confirm('Nem mentett módosítások vannak. Elhagyod az ügyet?')){location.hash=`case/${S.cid}/${S.tab}`;return;}S.dirty=false;S.invalid.clear();}
  if(parts[0]==='case'&&parts[1]){
    S.page='case';S.tab=parts[2]||'overview';
    if(S.cid!==parts[1]||!S.data&&staff()){
      if(S.dirty&&!confirm('Nem mentett módosítások vannak. Elhagyod az ügyet?')){location.hash=`case/${S.cid}/${S.tab}`;return;}
      S.cid=parts[1];S.lastSave=null;S.reviewScope='year';S.dirty=false;S.invalid.clear();S.data=null;shell('<div class="loading-panel"><span class="spinner"></span>A vizsgálat betöltése…</div>','Vizsgálat');
      try{const [r,list,users]=await Promise.all([api(`/cases/${S.cid}`),api('/cases'),staff()?api('/users'):Promise.resolve([])]);S.cases=list;S.users=users;if(r.client_view){S.clientCase=r;renderClientCase(r);return;}S.data=r.data;S.calc=r.calculation;S.version=r.version;S.status=r.status;S.clientUserId=r.client_user_id;S.year=Math.max(...r.data.years);S.scenario='base';S.scenarioCalc=null;}catch(e){toast(e.message,true);location.hash='';return;}
    }
    if(staff())renderCase();else renderClientCase(S.clientCase);
  }else if(parts[0]==='users'&&S.user.role==='admin'){S.page='users';S.users=await api('/users');renderUsers();}
  else {S.page='dashboard';S.cid=null;S.data=null;S.cases=await api('/cases');if(staff())S.users=await api('/users');renderDashboard();}
}
document.addEventListener('click',async(e)=>{
  const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  try{
    if(['year','tab'].includes(a)&&S.invalid.size){document.querySelector('[aria-invalid=true]')?.focus();throw Error('Javítsd a hibás számezőt a nézetváltás előtt. A mező mellett látható a szükséges formátum.');}
    if(a==='review-year'){S.year=Number(el.dataset.year);S.reviewScope='year';renderCase();return;}
    if(a==='resolve-check'){openCheck(Number(el.dataset.index),el.dataset.year);return;}
    if(a==='family-decision'){decisionModal(el.dataset.id,{first:el.dataset.first,second:el.dataset.second,basis:'persons'});return;}
    if(a==='download-graph'){await downloadNetwork(el.dataset.kind);return;}
    if(a==='reset-graph'){S.data.graph_positions={};markDirty();renderCase();return;}
    if(['edit-company','edit-person'].includes(a)&&performance.now()<graphClickSuppressedUntil)return;
    if(a==='close-modal'){closeModal();return;}
    if(a==='dashboard'){location.hash='';return;}
    if(a==='users'){location.hash='users';return;}
    if(a==='open-case'){location.hash=`case/${el.dataset.id}/overview`;return;}
    if(a==='tab'){location.hash=`case/${S.cid}/${el.dataset.tab}`;return;}
    if(a==='logout'){if(S.dirty&&!confirm('Kilépés előtt nem mentett módosítások vannak. Folytatod?'))return;await api('/auth/logout',{method:'POST'});S.user=null;S.data=null;S.dirty=false;location.hash='';renderAuth(false);return;}
    if(a==='new-case'){openNew();return;}
    if(a==='demo'){el.disabled=true;const r=await api('/cases/demo',{method:'POST'});location.hash=`case/${r.id}/overview`;return;}
    if(a==='import'){chooseFile('.xlsx',async file=>{toast('Az Excel feldolgozása…');const form=new FormData();form.append('file',file);const r=await api('/cases/import',{method:'POST',body:form});location.hash=`case/${r.id}/overview`;toast('Az Excel importálva. A kapcsolatok és források ellenőrzendők.');});return;}
    if(a==='template'){await download('/template','KKV_adatbekeres.xlsx',el);return;}
    if(a==='save'){await save();return;}
    if(a==='case-settings'){openSettings();return;}
    if(a==='edit-company'){entityModal('company',el.dataset.id);return;}
    if(a==='edit-person'){entityModal('person',el.dataset.id);return;}
    if(a==='edit-ownership'){ownershipModal(el.dataset.id);return;}
    if(a==='edit-family'){familyModal(el.dataset.id);return;}
    if(a==='edit-decision'){decisionModal(el.dataset.id);return;}
    if(a==='edit-financial'){financialModal(el.dataset.id);return;}
    if(a==='edit-event'){eventModal(el.dataset.id);return;}
    if(a==='edit-override'){overrideModal(el.dataset.id,el.dataset.year);return;}
    if(a==='edit-public'){publicModal();return;}
    if(a==='year'){S.year=Number(el.dataset.year);renderCase();return;}
    if(a==='delete-item'){S.data[el.dataset.list]=S.data[el.dataset.list].filter(x=>x.id!==el.dataset.id);markDirty();closeModal();renderCase();return;}
    if(a==='delete-override'){S.data.overrides=S.data.overrides.filter(o=>o.company!==el.dataset.id||o.year!==Number(el.dataset.year));markDirty();closeModal();renderCase();return;}
    if(a==='delete-entity'){
      const cid=el.dataset.id;if(cid===S.data.root)throw Error('A vizsgált vállalkozás nem távolítható el.');if(!confirm('A szereplő és a hozzá tartozó helyi adatok eltávolítása? A korábbi mentett verziók megmaradnak.'))return;
      if(S.data.graph_positions)delete S.data.graph_positions[cid];S.data.companies=S.data.companies.filter(c=>c.id!==cid);S.data.persons=S.data.persons.filter(p=>p.id!==cid);S.data.ownerships=S.data.ownerships.filter(o=>o.owner!==cid&&o.company!==cid);S.data.decisions=S.data.decisions.filter(d=>d.first!==cid&&d.second!==cid);S.data.families=S.data.families.filter(f=>f.first!==cid&&f.second!==cid);S.data.financials=S.data.financials.filter(f=>f.company!==cid).map(f=>({...f,included:f.included.filter(i=>i!==cid)}));S.data.overrides=S.data.overrides.filter(o=>o.company!==cid);markDirty();closeModal();renderCase();return;
    }
    if(a==='mnb'){
      el.disabled=true;el.innerHTML='<span class="spinner"></span> Lekérés…';const dateField=document.querySelector('[data-rate="date"]');const r=await api('/mnb?day='+encodeURIComponent(dateField.value));let rate=rateFor(S.year);if(rate)Object.assign(rate,r);else S.data.rates.push({year:S.year,...r});markDirty();renderCase();toast('Hivatalos MNB-árfolyam rögzítve.');return;
    }
    if(a==='export'){el.disabled=true;await save();if(S.dirty)throw Error('Új módosítás történt a mentés közben. Mentsd az exportálás előtt.');await download(`/cases/${S.cid}/report/${el.dataset.kind}`,`KKV_allasfoglalas_v${S.version}.${el.dataset.kind}`,el);return;}
    if(a==='client-export'){await download(`/cases/${S.cid}/report/${el.dataset.kind}`,`KKV_allasfoglalas.${el.dataset.kind}`,el);return;}
    if(a==='upload'){chooseFile('.pdf,.docx,.xlsx,.png,.jpg,.jpeg,.txt',async file=>{if(file.size>20*1024*1024)throw Error('A fájl legfeljebb 20 MB lehet.');const form=new FormData();form.append('file',file);await api(`/cases/${S.cid}/documents`,{method:'POST',body:form});await loadDocuments();toast('A dokumentum feltöltve.');});return;}
    if(a==='review-intake'){el.disabled=true;await api(`/cases/${S.cid}/intake/${el.dataset.id}/review`,{method:'POST'});if(S.tab==='review')await loadReviewIntake();else await loadDocuments();toast('Az ügyfélválasz feldolgozottként jelölve.');return;}
    if(a==='new-user'){modal('Felhasználó felvétele',`<div class="form-grid">${field('Teljes név','name','','text','required')}${field('Felhasználónév','username','','text','required minlength="3"')}${field('Kezdeti jelszó','password','','password','required minlength="12" autocomplete="new-password"')}${select('Szerepkör','role','analyst',Object.entries(roles))}</div>`,'user');return;}
    if(a==='view-version'){const r=await api(`/cases/${S.cid}/versions/${el.dataset.version}`);modal(`${r.version}. mentett verzió`,`<p class="modal-intro">${esc(r.data.title)} · ${esc(r.calculation.label)}${r.approved_at?' · Jóváhagyott pillanatkép':''}</p><p class="small-text muted">Visszaállításkor az aktuális ügy új verziója készül, és új szakértői jóváhagyás szükséges.</p><pre>${esc(JSON.stringify(r.data,null,2))}</pre>`,'restore',{snapshot:r});return;}
  }catch(err){toast(err.message,true);if(el.isConnected){el.disabled=false;if(a==='mnb')el.innerHTML=icon('download')+' MNB-lekérés';}}
});
document.addEventListener('submit',async(e)=>{
  e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
  try{
    if(form.id==='auth-form'){
      const body=Object.fromEntries(new FormData(form)),r=await api(form.dataset.setup==='true'?'/auth/setup':'/auth/login',{method:'POST',body});S.user=r.user;S.csrf=r.csrf;await route();return;
    }
    if(form.id==='modal-form'){await submitModal(form);return;}
    if(form.id==='approval-form'){
      const p=Object.fromEntries(new FormData(form));await api(`/cases/${S.cid}/approve`,{method:'POST',body:{version:S.version,financials:!!p.financials,relationships:!!p.relationships,rules:!!p.rules,note:p.note||''}});S.status='approved';renderCase();toast('A verzió jóváhagyva. Az állásfoglalás véglegesíthető.');return;
    }
    if(form.id==='intake-form'){await api(`/cases/${S.cid}/intake`,{method:'POST',body:{message:form.elements.message.value}});form.reset();await loadDocuments();toast('A válasz beküldve a szakértőnek.');return;}
  }catch(err){const target=form.id==='auth-form'?document.querySelector('#auth-error'):form.id==='modal-form'?document.querySelector('#modal-error'):null;if(target){target.textContent=err.message;target.classList.remove('hide');}else toast(err.message,true);}finally{if(submit&&submit.isConnected)submit.disabled=false;if(form.id==='approval-form')refreshApprovalAvailability();}
});
function onDataEdit(el){
  if(!S.data)return;
  if(el.dataset.fin){const key=el.dataset.id+S.year+el.dataset.fin;try{const f=financialFor(el.dataset.id,S.year),k=el.dataset.fin;if(['employees','turnover','balance'].includes(k)){const n=decimal(el.value);f[k]=k==='employees'?n:scale(n,3);}else f[k]=el.value||null;S.invalid.delete(key);el.removeAttribute('data-invalid');fieldValidity(el);markDirty();}catch(error){S.invalid.add(key);el.setAttribute('data-invalid','true');fieldValidity(el,error.message);markDirty();}}
  if(el.dataset.rate){const k=el.dataset.rate,key='rate'+S.year+k;let r=rateFor(S.year);if(!r){r={year:S.year,date:`${S.year}-12-31`,quoted:null,value:'1',source:'',confirmed:false};S.data.rates.push(r);}try{r[k]=k==='confirmed'?el.checked:k==='value'?decimal(el.value):el.value||null;if(k!=='confirmed'){r.confirmed=false;const box=document.querySelector('[data-rate="confirmed"]');if(box)box.checked=false;}S.invalid.delete(key);fieldValidity(el);markDirty();}catch(error){S.invalid.add(key);fieldValidity(el,error.message);markDirty();}}
}
document.addEventListener('input',e=>{if(e.target.id==='global-search'){S.search=e.target.value;if(S.page==='dashboard'){const pos=e.target.selectionStart;renderDashboard();const search=document.querySelector('#global-search');search.focus();search.setSelectionRange(pos,pos);}return;}if(e.target.dataset.fin||e.target.dataset.rate)onDataEdit(e.target);});
document.addEventListener('change',async e=>{
  if(e.target.dataset.fin||e.target.dataset.rate)onDataEdit(e.target);
  if(e.target.id==='review-scope'){S.reviewScope=e.target.value;renderCase();}
  if(e.target.name==='all_years'&&e.target.checked&&S.modal?.kind==='decision')document.querySelector('#modal-form [name=confirmed]').checked=true;
  if(e.target.closest('#approval-form'))refreshApprovalAvailability();
  if(e.target.id==='scenario'){try{S.scenario=e.target.value;if(S.scenario==='all'){await save();S.scenario='all';S.scenarioCalc=await api(`/cases/${S.cid}/calculate?scenario=all`);}renderCase();}catch(err){toast(err.message,true);}}
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='global-search'){e.preventDefault();location.hash='';return;}if(e.key==='Escape')closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#global-search')?.focus();}if(e.key==='Enter'&&e.target.matches('.case-row,.graph-node'))e.target.click();});
window.addEventListener('hashchange',()=>{if(S.user)route().catch(e=>toast(e.message,true));});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});
async function bootstrap(){try{const r=await api('/auth/me');S.user=r.user;S.csrf=r.csrf;await route();}catch(e){if(e.status===401){const r=await api('/auth/status');renderAuth(r.setup_required);}else{document.querySelector('#app').innerHTML='<div class="empty"><h2>A munkatér nem érhető el.</h2><p>'+esc(e.message)+'</p></div>';}}}
bootstrap();
